using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 removes "Discriminator" from the id by default.
            // Existing documents use "Blog|1" format, so preserve the old behavior.
            entity.HasDiscriminatorInJsonId();

            // Breaking change 2: EF Core 9 renames "$type" (discriminator property) from
            // "Discriminator" to "$type" by default. Existing documents use "Discriminator".
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: Cosmos DB does not support indexes defined via EF Core.
            // HasIndex() now throws at model validation in EF Core 9. Removed.
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

